import hashlib
import hmac
import json
import re

from payhook.errors import InvalidNotification

_TIMESTAMP_RE = re.compile(r"-?[0-9]+(?:\.[0-9]+)?")
_CURRENCY_RE = re.compile(r"[A-Z]{3}")
_SIGNATURE_PREFIX = "v1="
_MAX_SKEW_SECONDS = 300


def _header_value(headers, name):
    """Look up a header by case-insensitive name; return a stripped str or None."""
    lowered = name.lower()
    if hasattr(headers, "items"):
        pairs = headers.items()
    elif isinstance(headers, (list, tuple)):
        pairs = headers
    else:
        return None
    for pair in pairs:
        try:
            key, value = pair
        except (TypeError, ValueError):
            continue
        if isinstance(key, bytes):
            key = key.decode("latin-1", "replace")
        if not isinstance(key, str) or key.lower() != lowered:
            continue
        if isinstance(value, bytes):
            value = value.decode("latin-1", "replace")
        if not isinstance(value, str):
            return None
        return value.strip()
    return None


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    if isinstance(raw_body, str):
        body = raw_body.encode("utf-8")
    elif isinstance(raw_body, (bytes, bytearray, memoryview)):
        body = bytes(raw_body)
    else:
        raise InvalidNotification("notification body must be request bytes")

    if isinstance(secret, str):
        secret = secret.encode("utf-8")

    # Timestamp: present, decimal, and fresh within the acceptance window.
    timestamp_header = _header_value(headers, "X-Pay-Timestamp")
    if timestamp_header is None or not _TIMESTAMP_RE.fullmatch(timestamp_header):
        raise InvalidNotification("missing or malformed X-Pay-Timestamp header")
    try:
        timestamp = float(timestamp_header)
    except OverflowError:
        raise InvalidNotification("X-Pay-Timestamp is outside the acceptance window")
    if abs(timestamp - float(now)) > _MAX_SKEW_SECONDS:
        raise InvalidNotification("X-Pay-Timestamp is outside the acceptance window")

    # Signature: HMAC-SHA256 over "<timestamp>.<body>", compared in constant time.
    signature_header = _header_value(headers, "X-Pay-Signature")
    if signature_header is None or not signature_header.startswith(_SIGNATURE_PREFIX):
        raise InvalidNotification("missing or malformed X-Pay-Signature header")
    provided = signature_header[len(_SIGNATURE_PREFIX):].lower().encode("utf-8", "replace")
    signed_payload = timestamp_header.encode("ascii") + b"." + body
    expected = hmac.new(secret, signed_payload, hashlib.sha256).hexdigest().encode("ascii")
    if not hmac.compare_digest(expected, provided):
        raise InvalidNotification("X-Pay-Signature does not match the notification")

    # Body: a UTF-8 JSON object carrying the required payment fields.
    try:
        payload = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        raise InvalidNotification("notification body is not valid UTF-8 JSON")
    if not isinstance(payload, dict):
        raise InvalidNotification("notification body is not a JSON object")

    event_id = payload.get("event_id")
    account_id = payload.get("account_id")
    amount_minor = payload.get("amount_minor")
    currency = payload.get("currency")

    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("event_id must be a nonempty string")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("account_id must be a nonempty string")
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int) or amount_minor < 0:
        raise InvalidNotification("amount_minor must be a nonnegative integer")
    if not isinstance(currency, str) or not _CURRENCY_RE.fullmatch(currency):
        raise InvalidNotification("currency must be three uppercase ASCII letters")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }

