PYTHONPATH=src python3 - <<'EOF'
import hashlib, hmac, json
from payhook.errors import InvalidNotification
from payhook.receiver import parse_payment

SECRET = b"s"; NOW = 1760000000
def d(event, raw=None, secret=SECRET, stamp=str(NOW)):
    body = raw if raw is not None else json.dumps(event).encode()
    dig = hmac.new(secret, stamp.encode() + b"." + body, hashlib.sha256).hexdigest()
    return body, {"X-Pay-Timestamp": stamp, "X-Pay-Signature": "v1=" + dig}

ok = {"event_id": "e", "account_id": "a", "amount_minor": 5, "currency": "USD"}

b, h = d(ok, secret=b"other")
try:
    parse_payment(b, h, SECRET, NOW); print("FAIL (accepted): wrong secret")
except InvalidNotification: print("rejected: wrong secret")

for label, stamp in [("future >300s", str(NOW + 301)), ("past >300s", str(NOW - 301))]:
    b, h = d(ok, stamp=stamp)
    try:
        parse_payment(b, h, SECRET, NOW); print("FAIL (accepted):", label)
    except InvalidNotification: print("rejected:", label)

b, h = d(ok, stamp=str(NOW + 300))
print("accepted at exactly +300s skew:", parse_payment(b, h, SECRET, NOW) == ok)
b, h = d(ok, stamp=str(NOW - 300))
print("accepted at exactly -300s skew:", parse_payment(b, h, SECRET, NOW) == ok)

b, h = d(ok)
print("happy path:", parse_payment(b, h, SECRET, NOW) == ok)
print("zero amount allowed:", parse_payment(*d(dict(ok, amount_minor=0)), SECRET, NOW)["amount_minor"] == 0)

# lowercase header names + uppercase hex digest
h2 = {"x-pay-timestamp": str(NOW), "x-pay-signature": "v1=" + h["X-Pay-Signature"][3:].upper()}
print("case-insensitive headers / uppercase hex:", parse_payment(b, h2, SECRET, NOW) == ok)

# garbage timestamp and signature values
for label, hdrs in [
    ("non-numeric timestamp", {"X-Pay-Timestamp": "abc", "X-Pay-Signature": h["X-Pay-Signature"]}),
    ("nan timestamp", {"X-Pay-Timestamp": "nan", "X-Pay-Signature": h["X-Pay-Signature"]}),
    ("bad signature scheme", {"X-Pay-Timestamp": str(NOW), "X-Pay-Signature": "v2=" + h["X-Pay-Signature"][3:]}),
    ("empty signature", {"X-Pay-Timestamp": str(NOW), "X-Pay-Signature": ""}),
]:
    try:
        parse_payment(b, hdrs, SECRET, NOW); print("FAIL (accepted):", label)
    except InvalidNotification: print("rejected:", label)
EOF
